descriptor.templateCss:
.dg-card-container {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #a855f7;
  padding: 16px 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
  overflow: hidden;
  transition: border-top-color 0.3s ease;
}

.dg-card-container.running {
  border-top-color: #a855f7;
}

.dg-card-container.standby {
  border-top-color: #64748b;
}

.dg-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 24px;
}

.dg-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
  white-space: nowrap;
}

.dg-icon {
  font-size: 16px;
}

.dg-status-badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  padding: 2px 10px;
  border-radius: 20px;
  white-space: nowrap;
  transition: all 0.3s ease;
}

.dg-status-badge.running {
  color: #a855f7;
  border: 1.5px solid #a855f7;
  background: rgba(168, 85, 247, 0.12);
}

.dg-status-badge.standby {
  color: #94a3b8;
  border: 1.5px solid #94a3b8;
  background: rgba(148, 163, 184, 0.08);
}

.dg-metric-body {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 6px 0;
  min-height: 40px;
}

.metric-value {
  font-size: 40px;
  font-weight: 800;
  color: #a855f7;
  line-height: 1;
  transition: color 0.3s ease;
}

.metric-value.standby {
  color: #94a3b8;
}

.metric-unit {
  font-size: 20px;
  font-weight: 600;
  color: #94a3b8;
  white-space: nowrap;
}

.dg-divider {
  width: 100%;
  height: 1px;
  background: rgba(148, 163, 184, 0.15);
  margin: 8px 0 10px 0;
}

.dg-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  min-height: 38px;
}

.footer-left {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.footer-left .footer-label {
  font-size: 13px;
  font-weight: 500;
  color: #94a3b8;
  white-space: nowrap;
}

.footer-left .footer-subtext {
  font-size: 12px;
  color: #556987;
  margin-top: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.footer-right {
  display: flex;
  align-items: flex-end;
}

.footer-right .footer-value {
  font-size: 16px;
  font-weight: 700;
  white-space: nowrap;
  transition: color 0.3s ease;
}

.footer-right .footer-value.running {
  color: #a855f7;
}

.footer-right .footer-value.standby {
  color: #64748b;
}

descriptor.controllerScript:
self.onInit = function() {
  self.onDataUpdated();
};

self.onDataUpdated = function() {
  var data = self.ctx.data;
  var powerVal = 0.0;
  var estadoVal = "APAGADO";
  var isRunning = false;

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var lastVal = item.data[item.data.length - 1][1];
        var keyName = (item.dataKey.label || item.dataKey.name || "").toLowerCase();

        if (keyName.indexOf("potencia") !== -1 || keyName.indexOf("dg_") !== -1 || i === 0) {
          var num = parseFloat(lastVal);
          if (!isNaN(num)) powerVal = num;
        } else if (keyName.indexOf("estado") !== -1 || i === 1) {
          estadoVal = String(lastVal).toUpperCase();
        }
      }
    }
  }

  isRunning = powerVal > 0.5 || estadoVal.indexOf("MARCHA") !== -1 || estadoVal.indexOf("ON") !== -1 || estadoVal === "1";

  var modeClass = isRunning ? "running" : "standby";
  var badgeText = isRunning ? "EN MARCHA" : "STANDBY";
  var stateText = isRunning ? (estadoVal !== "APAGADO" ? estadoVal : "EN LÍNEA") : "APAGADO";

  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (container) {
    var card = container.querySelector('#dg-card');
    if (card) card.className = "dg-card-container " + modeClass;

    var elPower = container.querySelector('#dg-power-value');
    if (elPower) {
      elPower.textContent = powerVal.toFixed(1);
      elPower.className = "metric-value " + (isRunning ? "running" : "standby");
    }

    var elBadge = container.querySelector('#dg-status-badge');
    if (elBadge) {
      elBadge.textContent = badgeText;
      elBadge.className = "dg-status-badge " + modeClass;
    }

    var elState = container.querySelector('#dg-state-value');
    if (elState) {
      elState.textContent = stateText;
      elState.className = "footer-value " + modeClass;
    }
  }
};

self.onDestroy = function() {};
